-- Improve invite code generation to be more secure and less predictable
-- Use a combination of random UUID and timestamp for better uniqueness

-- Create a function to generate secure invite codes
CREATE OR REPLACE FUNCTION generate_secure_invite_code()
RETURNS TEXT AS $$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- Removed ambiguous characters
  result TEXT := '';
  i INTEGER;
BEGIN
  FOR i IN 1..8 LOOP
    result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  END LOOP;
  RETURN result;
END;
$$ LANGUAGE plpgsql VOLATILE;

-- Update the households table to use the new function
ALTER TABLE households 
  ALTER COLUMN invite_code 
  SET DEFAULT generate_secure_invite_code();

-- Add a function to prevent role escalation from client side
CREATE OR REPLACE FUNCTION prevent_role_escalation()
RETURNS TRIGGER AS $$
BEGIN
  -- If user is trying to change their own role
  IF NEW.id = auth.uid() THEN
    -- Children cannot change their role
    IF OLD.role = 'Child' AND NEW.role != OLD.role THEN
      RAISE EXCEPTION 'Children cannot change their own role';
    END IF;

    -- Users cannot escalate to Parent role without admin approval
    IF OLD.role != 'Parent' AND NEW.role = 'Parent' THEN
      RAISE EXCEPTION 'Role escalation to Parent requires admin approval';
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger to prevent role escalation
DROP TRIGGER IF EXISTS prevent_role_escalation_trigger ON users;
CREATE TRIGGER prevent_role_escalation_trigger
  BEFORE UPDATE ON users
  FOR EACH ROW
  WHEN (OLD.role IS DISTINCT FROM NEW.role)
  EXECUTE FUNCTION prevent_role_escalation();

-- Add a function to validate task updates for children
CREATE OR REPLACE FUNCTION validate_child_task_update()
RETURNS TRIGGER AS $$
DECLARE
  user_role TEXT;
BEGIN
  -- Get the user's role
  SELECT role INTO user_role FROM users WHERE id = auth.uid();

  -- If user is a child and assigned to this task
  IF user_role = 'Child' AND NEW.assigned_to_user_id = auth.uid() THEN
    -- Only allow status and completed_at changes
    IF OLD.title IS DISTINCT FROM NEW.title OR
       OLD.description IS DISTINCT FROM NEW.description OR
       OLD.assigned_to_user_id IS DISTINCT FROM NEW.assigned_to_user_id OR
       OLD.frequency IS DISTINCT FROM NEW.frequency OR
       OLD.due_date IS DISTINCT FROM NEW.due_date OR
       OLD.household_id IS DISTINCT FROM NEW.household_id OR
       OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id THEN
      RAISE EXCEPTION 'Children can only update task status and completion';
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger to validate child task updates
DROP TRIGGER IF EXISTS validate_child_task_update_trigger ON tasks;
CREATE TRIGGER validate_child_task_update_trigger
  BEFORE UPDATE ON tasks
  FOR EACH ROW
  EXECUTE FUNCTION validate_child_task_update();
